/** Colours Material 3 has no role for: read them with AppTheme.colors, e.g. AppTheme.colors.success.
 *  textPlaceholder is only for placeholders, disabled text, chevrons and decorative icons. */
@Immutable
data class ExtendedColors(
    val surface3: Color,
    val borderStrong: Color,
    val textPlaceholder: Color,
    val success: Color,
    val onSuccess: Color,
    val successContainer: Color,
    val warning: Color,
    val onWarning: Color,
    val warningContainer: Color,
    val info: Color,
    val onInfo: Color,
    val infoContainer: Color,
    val disabledFg: Color,
    val disabledBg: Color,
    val stateHover: Color,
    val statePressed: Color,
    val focus: Color,
    val selection: Color,
    val frost: Color,
    val frostBorder: Color,
)

