/** Motion: ease-out for most changes, a light spring for things that appear; e.g. tween(Motion.STANDARD_MS, easing = Motion.StandardEasing). */
object Motion {
    const val FAST_MS = 160
    val FastEasing = CubicBezierEasing(0.2f, 0f, 0f, 1f)
    const val STANDARD_MS = 240
    val StandardEasing = CubicBezierEasing(0.2f, 0f, 0f, 1f)
    const val SPRING_MS = 420
    val SpringEasing = CubicBezierEasing(0.34f, 1.36f, 0.64f, 1f)
}

/** Material 3 picks corners by size key: text fields use extraSmall, chips small, cards medium, sheets large. */
val AppShapes = Shapes(
    extraSmall = RoundedCornerShape(8.dp),
    small = RoundedCornerShape(8.dp),
    medium = RoundedCornerShape(12.dp),
    large = RoundedCornerShape(16.dp),
    extraLarge = RoundedCornerShape(16.dp)
)

/** Buttons are 12 dp (not Material's pill); chips and tags are full pills. AppButton and AppChip pass these. */
val ButtonShape = RoundedCornerShape(12.dp)
val ChipShape = CircleShape

