@Composable
fun AppTheme(dark: Boolean = isSystemInDarkTheme(), content: @Composable () -> Unit) {
    CompositionLocalProvider(LocalExtendedColors provides if (dark) DarkExtendedColors else LightExtendedColors) {
        MaterialTheme(
            colorScheme = if (dark) DarkColors else LightColors,
            shapes = AppShapes,
            typography = AppTypography,
            content = content,
        )
    }
}

/** Primary button: primary fill, on-primary label, 12 dp corners, 50 dp tall, no shadow. Use it instead of Button. */
@Composable
fun AppButton(
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    colors: ButtonColors = ButtonDefaults.buttonColors(
        disabledContainerColor = AppTheme.colors.disabledBg,
        disabledContentColor = AppTheme.colors.disabledFg,
    ),
    content: @Composable RowScope.() -> Unit,
) = Button(
    onClick = onClick,
    modifier = modifier.heightIn(min = AppSize.controlLg),
    enabled = enabled,
    shape = ButtonShape,
    colors = colors,
    content = content,
)

/** Secondary button: surface fill, 1 dp border, text-coloured label, same shape and height as AppButton. */
@Composable
fun AppOutlinedButton(
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    content: @Composable RowScope.() -> Unit,
) = OutlinedButton(
    onClick = onClick,
    modifier = modifier.heightIn(min = AppSize.controlLg),
    enabled = enabled,
    shape = ButtonShape,
    colors = ButtonDefaults.outlinedButtonColors(
        containerColor = MaterialTheme.colorScheme.surface,
        contentColor = MaterialTheme.colorScheme.onSurface,
    ),
    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
    content = content,
)

/** Filter chip: full pill, subhead label (bodyMedium; FilterChip's default labelLarge is the 17 sp headline);
 *  unselected = surface fill, 1 dp border and text-2 label; selected = primary-container fill, on-primary-container
 *  label, no border. Use it instead of FilterChip. */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AppChip(
    selected: Boolean,
    onClick: () -> Unit,
    label: String,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    leadingIcon: (@Composable () -> Unit)? = null,
) = FilterChip(
    selected = selected,
    onClick = onClick,
    label = { Text(label, style = MaterialTheme.typography.bodyMedium, fontWeight = if (selected) FontWeight.W600 else null) },
    modifier = modifier,
    enabled = enabled,
    leadingIcon = leadingIcon,
    shape = ChipShape,
    colors = FilterChipDefaults.filterChipColors(containerColor = MaterialTheme.colorScheme.surface),
    border = FilterChipDefaults.filterChipBorder(
        enabled = enabled,
        selected = selected,
        borderColor = MaterialTheme.colorScheme.outlineVariant,
    ),
)

/** Status tag: the status colour on its own container, full pill, with a leading status icon
 *  (✓ / ! / i at IconSize.sm, tinted with the status colour). Always pass the icon when the status
 *  shares the primary's accent (info on a blue theme, success on a green one): without it the tag
 *  reads as a selected chip.
 *  e.g. StatusTag("已完成", AppTheme.colors.success, AppTheme.colors.successContainer,
 *           icon = { Icon(Icons.Rounded.Check, contentDescription = null) }) */
@Composable
fun StatusTag(
    text: String,
    color: Color,
    container: Color,
    modifier: Modifier = Modifier,
    icon: (@Composable () -> Unit)? = null,
) = Surface(modifier = modifier, shape = ChipShape, color = container, contentColor = color) {
    Row(
        modifier = Modifier.padding(start = if (icon != null) 7.dp else 10.dp, end = 10.dp, top = 3.dp, bottom = 3.dp),
        horizontalArrangement = Arrangement.spacedBy(4.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        if (icon != null) Box(Modifier.size(IconSize.sm), contentAlignment = Alignment.Center) { icon() }
        Text(text, style = MaterialTheme.typography.labelSmall)
    }
}
